const dgram = require('dgram');
const net = require('net');
const crypto = require('crypto');

class DNSResolver {
  constructor(options = {}) {
    this.upstream = options.upstream || '8.8.8.8';
    this.port = options.port || 53;
    this.maxRetries = options.maxRetries || 3;
    this.timeout = options.timeout || 5000;
    this.rateLimit = new RateLimiter(options.rps || 100);
    this.cache = new Map();
    this.logStream = null;
    this.logPath = options.logPath || '/var/log/dns-resolver.log';
  }

  initLogging(logPath) {
    const fs = require('fs');
    this.logStream = fs.createWriteStream(logPath || this.logPath, { flags: 'a' });
  }

  formatLogEntry(clientAddr, queryName, queryType, status) {
    const timestamp = new Date().toISOString();
    const sanitized = this._sanitizeForLog(queryName);
    return `[${timestamp}] client=${clientAddr} query=${sanitized} type=${queryType} status=${status}`;
  }

  _sanitizeForLog(input) {
    // Remove null bytes and control characters below 0x20
    // but preserve valid DNS label characters
    let result = '';
    for (let i = 0; i < input.length; i++) {
      const code = input.charCodeAt(i);
      if (code >= 0x20 && code <= 0x7e) {
        result += input[i];
      }
    }
    return result;
  }

  writeLog(clientAddr, queryName, queryType, status) {
    if (!this.logStream) return;
    const entry = this.formatLogEntry(clientAddr, queryName, queryType, status);
    this.logStream.write(entry + '\n');
  }

  async resolve(queryName, queryType, clientAddr) {
    if (!this.rateLimit.allow(clientAddr)) {
      this.writeLog(clientAddr, queryName, queryType, 'RATE_LIMITED');
      return { error: 'rate_limited', rcode: 5 };
    }

    const cacheKey = `${queryName}:${queryType}`;
    if (this.cache.has(cacheKey)) {
      const cached = this.cache.get(cacheKey);
      if (Date.now() - cached.ts < cached.ttl * 1000) {
        this.writeLog(clientAddr, queryName, queryType, 'CACHE_HIT');
        return cached.response;
      }
      this.cache.delete(cacheKey);
    }

    return this._resolveWithRetry(queryName, queryType, clientAddr, 0);
  }

  async _resolveWithRetry(queryName, queryType, clientAddr, attempt) {
    try {
      const response = await this._sendQuery(queryName, queryType);
      this.writeLog(clientAddr, queryName, queryType, 'SUCCESS');
      if (response.ttl > 0) {
        this.cache.set(`${queryName}:${queryType}`, {
          response, ts: Date.now(), ttl: response.ttl
        });
      }
      return response;
    } catch (err) {
      if (attempt < this.maxRetries) {
        const backoff = Math.min(1000 * Math.pow(2, attempt), 8000);
        await new Promise(r => setTimeout(r, backoff));
        return this._resolveWithRetry(queryName, queryType, clientAddr, attempt + 1);
      }
      this.writeLog(clientAddr, queryName, queryType, 'FAILED');
      return { error: 'resolution_failed', rcode: 2 };
    }
  }

  _sendQuery(queryName, queryType) {
    return new Promise((resolve, reject) => {
      const socket = dgram.createSocket('udp4');
      const txid = crypto.randomBytes(2);
      const packet = this._buildQuery(txid, queryName, queryType);

      const timer = setTimeout(() => {
        socket.close();
        reject(new Error('timeout'));
      }, this.timeout);

      socket.on('message', (msg) => {
        clearTimeout(timer);
        socket.close();
        try {
          const parsed = this._parseResponse(msg, txid);
          resolve(parsed);
        } catch (e) {
          reject(e);
        }
      });

      socket.send(packet, this.port, this.upstream, (err) => {
        if (err) {
          clearTimeout(timer);
          socket.close();
          reject(err);
        }
      });
    });
  }

  _buildQuery(txid, name, type) {
    const typeMap = { 'A': 1, 'AAAA': 28, 'MX': 15, 'TXT': 16, 'CNAME': 5 };
    const qtype = typeMap[type] || 1;
    const labels = name.split('.');
    let qname = Buffer.alloc(0);
    for (const label of labels) {
      const len = Buffer.from([label.length]);
      const data = Buffer.from(label, 'ascii');
      qname = Buffer.concat([qname, len, data]);
    }
    qname = Buffer.concat([qname, Buffer.from([0])]);
    const header = Buffer.alloc(12);
    txid.copy(header, 0);
    header.writeUInt16BE(0x0100, 2);
    header.writeUInt16BE(1, 4);
    const question = Buffer.alloc(4);
    question.writeUInt16BE(qtype, 0);
    question.writeUInt16BE(1, 2);
    return Buffer.concat([header, qname, question]);
  }

  _parseResponse(msg, expectedTxid) {
    if (msg.length < 12) throw new Error('invalid response');
    if (msg[0] !== expectedTxid[0] || msg[1] !== expectedTxid[1]) {
      throw new Error('txid mismatch');
    }
    const rcode = msg[3] & 0x0f;
    const ancount = msg.readUInt16BE(6);
    return { rcode, answers: ancount, ttl: 300 };
  }
}

class RateLimiter {
  constructor(maxRps) {
    this.maxRps = maxRps;
    this.windows = new Map();
  }

  allow(key) {
    const now = Math.floor(Date.now() / 1000);
    const windowKey = `${key}:${now}`;
    const count = this.windows.get(windowKey) || 0;
    if (count >= this.maxRps) return false;
    this.windows.set(windowKey, count + 1);
    // Cleanup old windows
    if (Math.random() < 0.01) {
      for (const [k] of this.windows) {
        const ts = parseInt(k.split(':').pop());
        if (now - ts > 10) this.windows.delete(k);
      }
    }
    return true;
  }
}

class DNSServer {
  constructor(resolver) {
    this.resolver = resolver;
    this.server = dgram.createSocket('udp4');
  }

  start(port = 5353) {
    this.resolver.initLogging();
    this.server.on('message', async (msg, rinfo) => {
      if (msg.length < 12) return;
      const txid = msg.slice(0, 2);
      const queryName = this._extractQueryName(msg);
      const queryType = this._extractQueryType(msg);
      const clientAddr = `${rinfo.address}:${rinfo.port}`;
      const result = await this.resolver.resolve(queryName, queryType, clientAddr);
      const response = this._buildResponse(txid, result);
      this.server.send(response, rinfo.port, rinfo.address);
    });
    this.server.bind(port);
  }

  _extractQueryName(msg) {
    let offset = 12;
    const labels = [];
    while (offset < msg.length && msg[offset] !== 0) {
      const len = msg[offset];
      offset++;
      if (offset + len > msg.length) break;
      labels.push(msg.slice(offset, offset + len).toString());
      offset += len;
    }
    return labels.join('.');
  }

  _extractQueryType(msg) {
    let offset = 12;
    while (offset < msg.length && msg[offset] !== 0) {
      offset += msg[offset] + 1;
    }
    offset++;
    if (offset + 2 > msg.length) return 'A';
    const typeMap = { 1: 'A', 28: 'AAAA', 15: 'MX', 16: 'TXT', 5: 'CNAME' };
    return typeMap[msg.readUInt16BE(offset)] || 'A';
  }

  _buildResponse(txid, result) {
    const header = Buffer.alloc(12);
    txid.copy(header, 0);
    header.writeUInt16BE(0x8180, 2);
    header.writeUInt16BE(0, 4);
    header.writeUInt16BE(result.answers || 0, 6);
    return header;
  }
}

module.exports = { DNSResolver, DNSServer, RateLimiter };
